// Reminders
// ============================================

/**
 * Set a reminder for a user
 * Requires user token (xoxp-) with reminders:write scope
 * Falls back to scheduled DM if no user token
 */
export async function setReminder(
  userId: string,
  text: string,
  time: Date | string
): Promise<{ success: boolean; reminderId?: string; error?: string; fallbackUsed?: boolean }> {
  // If no user token, return error indicating fallback should be used
  if (!userClient) {
    logger.warn('No user token available for reminders API');
    return { 
      success: false, 
      error: 'NO_USER_TOKEN',
      fallbackUsed: false 
    };
  }

  try {
    // Time can be a Date or a natural language string like "in 5 minutes", "tomorrow at 9am"
    let timeParam: string | number;

    if (time instanceof Date) {
      timeParam = Math.floor(time.getTime() / 1000);
    } else {
      // Natural language time - Slack can parse this
      timeParam = time;
    }

    logger.info(`Setting reminder for user ${userId}: "${text}" at ${time}`);

    const result = await userClient.reminders.add({
      user: userId,
      text: text,
      time: timeParam,
    });

    logger.info(`Reminder set successfully, ID: ${result.reminder?.id}`);
    return { success: true, reminderId: result.reminder?.id };
  } catch (error: any) {
    const slackError = error?.data?.error || error?.message || String(error);
    logger.error(`Failed to set reminder: ${slackError}`, { error: error?.data || error });

    const errorMessages: Record<string, string> = {
      'cannot_parse': 'Could not understand the time. Try "in 5 minutes" or "tomorrow at 9am".',
      'time_in_past': 'The reminder time is in the past.',
      'user_not_found': 'User not found.',
      'missing_scope': 'Missing permission: reminders:write. Please add this scope to the Slack app.',
      'not_allowed_token_type': 'Reminders require a User Token (xoxp-). Please configure SLACK_USER_TOKEN.',
    };

    return { success: false, error: errorMessages[slackError] || slackError };
  }
}

/**
 * List reminders for a user
 * Requires user token (xoxp-) with reminders:read scope
 */
export async function listReminders(): Promise<{ id: string; text: string; time: Date; complete: boolean }[]> {
  if (!userClient) {
    logger.warn('No user token available for reminders API');
    return [];
  }

  try {
    const result = await userClient.reminders.list();

    return (result.reminders || []).map((r: any) => ({
      id: r.id,
      text: r.text,
      time: new Date(r.time * 1000),
      complete: r.complete_ts > 0,
    }));
  } catch (error: any) {
    logger.error('Failed to list reminders', { error: error?.data || error });
    return [];
  }
}

/**
 * Delete a reminder
 * Requires user token (xoxp-) with reminders:write scope
 */
export async function deleteReminder(
  reminderId: string
): Promise<{ success: boolean; error?: string }> {
  if (!userClient) {
    return { success: false, error: 'No user token configured for reminders' };
  }

  try {
    await userClient.reminders.delete({ reminder: reminderId });
    return { success: true };
  } catch (error: any) {
    const slackError = error?.data?.error || error?.message || String(error);
    logger.error(`Failed to delete reminder: ${slackError}`);
    return { success: false, error: slackError };
  }
}

import time
from typing import Optional, List, Dict, Any, Tuple
from datetime import datetime

try:
    from slack_sdk import WebClient
    from slack_sdk.errors import SlackApiError
except ImportError:
    WebClient = None
    class SlackApiError(Exception):
        response = {"error": "slack_sdk not installed"}
from ..config import config
from ..utils.logger import create_module_logger

logger = create_module_logger("slack-actions")

_web_client: Optional[WebClient] = None
_user_client: Optional[WebClient] = None

def get_slack_clients() -> tuple[WebClient, Optional[WebClient]]:
    global _web_client, _user_client
    if _web_client is None:
        _web_client = WebClient(token=config.slack.bot_token)
    if _user_client is None and config.slack.user_token:
        _user_client = WebClient(token=config.slack.user_token)
    return _web_client, _user_client

# ============================================
# User Operations
# ============================================

def get_user_info(user_id: str) -> Optional[Dict[str, Any]]:
    client, _ = get_slack_clients()
    try:
        res = client.users_info(user=user_id)
        user = res.get("user")
        if not user:
            return None
        return {
            "id": user["id"],
            "name": user.get("name", "unknown"),
            "real_name": user.get("real_name", user.get("name", "unknown")),
            "email": user.get("profile", {}).get("email"),
        }
    except SlackApiError as e:
        logger.error(f"Error fetching user {user_id}: {e.response['error']}")
        return None

def find_user(query: str) -> Optional[Dict[str, Any]]:
    client, _ = get_slack_clients()
    clean_query = query.lstrip("@").lower()
    try:
        res = client.users_list()
        for user in res.get("members", []):
            if user.get("deleted"):
                continue
            name = user.get("name", "").lower()
            real = user.get("real_name", "").lower()
            email = user.get("profile", {}).get("email", "").lower()
            if clean_query in (name, real, email):
                return {
                    "id": user["id"],
                    "name": user.get("name", "unknown"),
                    "real_name": user.get("real_name", user.get("name", "unknown")),
                }
        return None
    except SlackApiError as e:
        logger.error(f"Error finding user {query}: {e.response['error']}")
        return None

def list_users() -> List[Dict[str, Any]]:
    client, _ = get_slack_clients()
    try:
        res = client.users_list()
        users = []
        for u in res.get("members", []):
            if not u.get("deleted") and not u.get("is_bot"):
                users.append({
                    "id": u["id"],
                    "name": u.get("name", ""),
                    "real_name": u.get("real_name", u.get("name", "")),
                    "email": u.get("profile", {}).get("email")
                })
        return users
    except SlackApiError as e:
        logger.error(f"Error listing users: {e.response['error']}")
        return []

# ============================================
# Channel Operations
# ============================================

def find_channel(query: str) -> Optional[Dict[str, Any]]:
    client, _ = get_slack_clients()
    clean_query = query.lstrip("#").lower()
    try:
        res = client.conversations_list(types="public_channel,private_channel", limit=200)
        for ch in res.get("channels", []):
            if ch.get("name", "").lower() == clean_query or ch.get("id", "").lower() == clean_query:
                return {
                    "id": ch["id"],
                    "name": ch.get("name", ""),
                    "is_member": ch.get("is_member", False),
                    "is_private": ch.get("is_private", False)
                }
        return None
    except SlackApiError as e:
        logger.error(f"Error finding channel {query}: {e.response['error']}")
        return None

def list_channels() -> List[Dict[str, Any]]:
    client, _ = get_slack_clients()
    try:
        res = client.conversations_list(types="public_channel,private_channel", limit=100)
        channels = []
        for ch in res.get("channels", []):
            if not ch.get("is_archived"):
                channels.append({
                    "id": ch["id"],
                    "name": ch.get("name", ""),
                    "is_member": ch.get("is_member", False),
                    "is_private": ch.get("is_private", False)
                })
        return channels
    except SlackApiError as e:
        logger.error(f"Error listing channels: {e.response['error']}")
        return []

# ============================================
# Messaging Operations
# ============================================

def send_message(target: str, message: str, thread_ts: Optional[str] = None) -> Dict[str, Any]:
    client, _ = get_slack_clients()
    channel_id = target

    # Check if target is a channel name or username
    if target.startswith("#"):
        ch = find_channel(target)
        if not ch:
            return {"success": False, "error": f"Channel {target} not found"}
        channel_id = ch["id"]
    elif target.startswith("@"):
        u = find_user(target)
        if not u:
            return {"success": False, "error": f"User {target} not found"}
        # Open DM
        dm = client.conversations_open(users=u["id"])
        channel_id = dm["channel"]["id"]

    try:
        res = client.chat_postMessage(channel=channel_id, text=message, thread_ts=thread_ts)
        return {"success": True, "ts": res["ts"], "channel": channel_id}
    except SlackApiError as e:
        logger.error(f"Error sending message to {target}: {e.response['error']}")
        return {"success": False, "error": e.response["error"]}

def get_channel_history(channel_id: str, limit: int = 20) -> List[Dict[str, Any]]:
    client, _ = get_slack_clients()
    try:
        res = client.conversations_history(channel=channel_id, limit=limit)
        messages = []
        for m in res.get("messages", []):
            if not m.get("subtype"):
                messages.append({
                    "ts": m.get("ts"),
                    "user": m.get("user"),
                    "text": m.get("text", ""),
                    "thread_ts": m.get("thread_ts")
                })
        return messages
    except SlackApiError as e:
        logger.error(f"Error fetching channel history: {e.response['error']}")
        return []

def search_messages(query: str, limit: int = 10) -> List[Dict[str, Any]]:
    client, user_client = get_slack_clients()
    # Slack search.messages requires user token (xoxp-)
    search_client = user_client or client
    try:
        res = search_client.search_messages(query=query, count=limit)
        matches = res.get("messages", {}).get("matches", [])
        return [
            {
                "text": m.get("text"),
                "channel": m.get("channel", {}).get("name"),
                "username": m.get("username"),
                "ts": m.get("ts"),
